type tableRequest struct {
	Method string            `json:"method"`
	Path   string            `json:"path"`
	Query  map[string]string `json:"query"`
	Body   any               `json:"body"`
	// HasBody tells an explicit body (even null) from none.
	HasBody bool `json:"-"`
}

func (r *tableRequest) UnmarshalJSON(data []byte) error {
	type plain tableRequest
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return err
	}
	if err := json.Unmarshal(data, (*plain)(r)); err != nil {
		return err
	}
	_, r.HasBody = raw["body"]
	return nil
}

type tableStep struct {
	Call tableRequest `json:"call"`
	Each *struct {
		List tableRequest `json:"list"`
		Page struct {
			Kind  string   `json:"kind"`
			Param string   `json:"param"`
			Size  int      `json:"size"`
			Next  []string `json:"next"`
		} `json:"page"`
		Where map[string]any `json:"where"`
	} `json:"each"`
	Fallback *struct {
		Status  int                          `json:"status"`
		Code    string                       `json:"code"`
		Reports components.EnforcementAction `json:"reports"`
		Steps   []tableStep                  `json:"steps"`
	} `json:"fallback"`
}

type tableRule struct {
	Flow      components.Flow                                               `json:"flow"`
	On        map[components.AccountDecision][]components.EnforcementAction `json:"on"`
	Reinstate map[components.AccountDecision][]components.EnforcementAction `json:"reinstate"`
}

type tableProvider struct {
	BaseURL string                                       `json:"base_url"`
	Actions map[components.EnforcementAction][]tableStep `json:"actions"`
}

var actionTable = func() (table struct {
	Lifecycle map[components.EnforcementState]tableRule `json:"lifecycle"`
	Providers map[string]tableProvider                  `json:"providers"`
	Limits    struct {
		Retries   int `json:"retries"`
		BudgetMS  int `json:"budget_ms"`
		BackoffMS int `json:"backoff_ms"`
		MaxPages  int `json:"max_pages"`
	} `json:"limits"`
}) {
	if err := json.Unmarshal([]byte(actionTableJSON), &table); err != nil {
		panic("noresponse: the action table does not parse: " + err.Error())
	}
	return table
}()

// AccountStateAnswer is where the account is in your flow, from GetAccountState.
type AccountStateAnswer struct {
	State components.EnforcementState
	// UserID is the provider's user id. Empty means the account id, as when
	// you assess with the provider's user id.
	UserID string
	// EnforcedRiskVersion is the risk_version you last enforced (a result's
	// RiskVersion that you stored). An account at or below it is skipped.
	EnforcedRiskVersion *int64
}

// ActionProvider runs one action in an identity provider. Build one with
// IdentityProvider or CustomProvider.
type ActionProvider interface {
	Name() components.EnforcementProvider
	// Run takes the action and returns any other action that had to run
	// with it (Auth0 restricts to end a session).
	Run(ctx context.Context, action components.EnforcementAction, userID string) ([]components.EnforcementAction, error)
}

// FlowPolicy is your choice for one flow.
type FlowPolicy struct {
	// Reinstate lifts a restriction once the flow's decision is allow again. Off by default.
	Reinstate bool
}

// EnforcementOptions configures HandleRiskChange and EnforceAccount.
type EnforcementOptions struct {
	Provider ActionProvider
	// GetAccountState returns the account's state in your flow, or nil for
	// an account you do not hold. An error fails the delivery so it is retried.
	GetAccountState func(ctx context.Context, account components.Account) (*AccountStateAnswer, error)
	// Flows is keyed by flow.
	Flows map[components.Flow]FlowPolicy
	// Webhook options for ConstructEvent.
	Webhook []WebhookOption
}

// EnforcementSkip says why nothing was done.
type EnforcementSkip string

const (
	// SkipNotActionable: not account.risk_changed, or a test event.
	SkipNotActionable EnforcementSkip = "not_actionable"
	// SkipAccountGone: GET answered 404, the account was erased.
	SkipAccountGone EnforcementSkip = "account_gone"
	// SkipUnknownUser: GetAccountState returned nil.
	SkipUnknownUser EnforcementSkip = "unknown_user"
	// SkipAlreadyEnforced: the account's risk_version is at or below EnforcedRiskVersion.
	SkipAlreadyEnforced EnforcementSkip = "already_enforced"
)

// Enforced is one recorded enforcement.
type Enforced struct {
	Flow      components.Flow
	Action    components.EnforcementAction
	Status    components.EnforcementStatus
	ErrorCode string
}

// EnforcementResult is what was done.
type EnforcementResult struct {
	// Event is the verified event, from HandleRiskChange. Answer an
	// endpoint.verification with its challenge.
	Event   *components.WebhookEvent
	Account *components.Account
	State   components.EnforcementState
	// RiskVersion is the risk_version acted on. Store it and return it as EnforcedRiskVersion.
	RiskVersion int64
	// Skipped is empty when the account was enforced.
	Skipped EnforcementSkip
	// Enforcements is what was recorded, in order.
	Enforcements []Enforced
}

// ProviderActionError is returned when the provider refuses an action or
// cannot be reached (Status 0). Answer the webhook with a 5xx so it is
// delivered again.
type ProviderActionError struct {
	Provider string
	Status   int
	Message  string
	// Code is the provider's error code, such as Auth0's errorCode
	// "insufficient_scope", when it sent one.
	Code string
}

func (e *ProviderActionError) Error() string { return "noresponse: " + e.Message }

// HandleRiskChange verifies an account.risk_changed delivery and enforces the
// account's current risk. A delivery that fails verification returns a
// *WebhookVerificationError before anything is read; any other event, and a
// test event, does nothing.
func HandleRiskChange(ctx context.Context, client *NoResponse, payload []byte, headers http.Header, secrets map[string]string, opts *EnforcementOptions) (*EnforcementResult, error) {
	if opts == nil || opts.Provider == nil || opts.GetAccountState == nil {
		return nil, errors.New("noresponse: HandleRiskChange needs Provider and GetAccountState")
	}
	event, err := ConstructEvent(payload, headers, secrets, opts.Webhook...)
	if err != nil {
		return nil, err
	}
	changed := event.AccountRiskChangedEvent
	if event.Type != components.WebhookEventTypeAccountRiskChanged || changed == nil || (changed.Test != nil && *changed.Test) {
		return &EnforcementResult{Event: event, Skipped: SkipNotActionable}, nil
	}
	response, err := client.Accounts.Get(ctx, changed.Data.Account.ID)
	if err != nil {
		var gone *apierrors.NotFoundError
		if errors.As(err, &gone) {
			return &EnforcementResult{Event: event, Skipped: SkipAccountGone}, nil
		}
		return nil, err
	}
	result, err := EnforceAccount(ctx, client, response.Result, opts)
	if result != nil {
		result.Event = event
	}
	return result, err
}

func decisionFor(account components.Account, flow components.Flow) components.AccountDecision {
	switch flow {
	case components.FlowAccountCreation:
		return account.DecisionsByFlow.AccountCreation
	case components.FlowLogin:
		return account.DecisionsByFlow.Login
	default:
		return account.DecisionsByFlow.Purchase
	}
}

// EnforceAccount enforces one account as read: the account a handler
// fetched, or one from Accounts.ListChanged with unenforced when catching up.
func EnforceAccount(ctx context.Context, client *NoResponse, account components.Account, opts *EnforcementOptions) (*EnforcementResult, error) {
	if opts == nil || opts.Provider == nil || opts.GetAccountState == nil {
		return nil, errors.New("noresponse: EnforceAccount needs Provider and GetAccountState")
	}
	answer, err := opts.GetAccountState(ctx, account)
	if err != nil {
		return nil, err
	}
	if answer == nil {
		return &EnforcementResult{Account: &account, Skipped: SkipUnknownUser}, nil
	}
	state := answer.State
	rule, ok := actionTable.Lifecycle[state]
	if !ok {
		return nil, fmt.Errorf("noresponse: unknown account state %q", state)
	}
	result := &EnforcementResult{Account: &account, State: state, RiskVersion: account.RiskVersion}
	if answer.EnforcedRiskVersion != nil && account.RiskVersion <= *answer.EnforcedRiskVersion {
		result.Skipped = SkipAlreadyEnforced
		return result, nil
	}
	flow := rule.Flow
	decision := decisionFor(account, flow)
	actions, adverse := rule.On[decision]
	if !adverse && opts.Flows[flow].Reinstate {
		actions = rule.Reinstate[decision]
	}
	provider := opts.Provider
	record := func(action components.EnforcementAction, status components.EnforcementStatus, errorCode string) error {
		body := components.EnforcementRequest{
			RiskVersion: account.RiskVersion,
			Flow:        flow,
			Action:      action,
			StateBefore: state,
			Status:      status,
			Provider:    provider.Name(),
		}
		if errorCode != "" {
			body.ErrorCode = &errorCode
		}
		if _, err := client.Accounts.RecordEnforcement(ctx, account.ID, body); err != nil {
			return err
		}
		result.Enforcements = append(result.Enforcements, Enforced{Flow: flow, Action: action, Status: status, ErrorCode: errorCode})
		return nil
	}
	if len(actions) == 0 {
		// A decision that needs nothing, allow too, still counts as handled, so the account leaves the unenforced feed.
		if err := record(components.EnforcementActionNone, components.EnforcementStatusApplied, ""); err != nil {
			return nil, err
		}
		return result, nil
	}
	userID := answer.UserID
	if userID == "" {
		userID = account.ID
	}
	recorded := map[components.EnforcementAction]bool{}
	for _, action := range actions {
		alsoRan, err := provider.Run(ctx, action, userID)
		if err != nil {
			if recordErr := record(action, components.EnforcementStatusFailed, failureCode(string(provider.Name()), err)); recordErr != nil {
				return nil, errors.Join(err, recordErr)
			}
			return nil, err
		}
		for _, ran := range append(alsoRan, action) {
			if recorded[ran] {
				continue
			}
			recorded[ran] = true
			if err := record(ran, components.EnforcementStatusApplied, ""); err != nil {
				return nil, err
			}
		}
	}
	return result, nil
}

var slug = regexp.MustCompile(`^[a-z0-9_.-]+$`)

// failureCode is the error_code of a failed action: the provider's code,
// else its HTTP status, as <provider>.<code>.
func failureCode(provider string, err error) string {
	suffix := "error"
	var refused *ProviderActionError
	var coded interface{ ErrorCode() string }
	switch {
	case errors.As(err, &refused) && slug.MatchString(strings.ToLower(refused.Code)):
		suffix = strings.ToLower(refused.Code)
	case errors.As(err, &refused) && refused.Status == 0:
		suffix = "unreachable"
	case errors.As(err, &refused):
		suffix = "http_" + strconv.Itoa(refused.Status)
	case errors.As(err, &coded) && slug.MatchString(strings.ToLower(coded.ErrorCode())):
		suffix = strings.ToLower(coded.ErrorCode())
	}
	code := provider + "." + suffix
	if len(code) > 128 {
		code = code[:128]
	}
	return code
}

// IdentityProviderOptions holds the admin API credentials.
type IdentityProviderOptions struct {
	// Token is the Clerk secret key, WorkOS API key or Auth0 Management API token.
	Token string
	// Domain is the Auth0 tenant domain, such as example.eu.auth0.com.
	Domain string
	// BaseURL replaces the table's admin API base URL (or Domain).
	BaseURL string
	// HTTPClient defaults to an http.Client with a 10 s timeout.
	HTTPClient HTTPClient
}

type identityProvider struct {
	name          components.EnforcementProvider
	spec          tableProvider
	base          string
	authorization string
	http          HTTPClient
}

// IdentityProvider is Clerk ("clerk"), WorkOS ("workos") or Auth0 ("auth0"),
// run from the shared action table.
func IdentityProvider(name string, options IdentityProviderOptions) (ActionProvider, error) {
	spec, ok := actionTable.Providers[name]
	if !ok {
		return nil, fmt.Errorf("noresponse: unknown identity provider %q", name)
	}
	if options.Token == "" {
		return nil, fmt.Errorf("noresponse: %s needs Token", name)
	}
	base := options.BaseURL
	if base == "" {
		base = spec.BaseURL
	}
	if strings.Contains(base, "{domain}") {
		if options.Domain == "" {
			return nil, fmt.Errorf("noresponse: %s needs Domain or BaseURL", name)
		}
		base = strings.ReplaceAll(base, "{domain}", options.Domain)
	}
	client := options.HTTPClient
	if client == nil {
		client = &http.Client{Timeout: 10 * time.Second}
	}
	return &identityProvider{
		name:          components.EnforcementProvider(name),
		spec:          spec,
		base:          strings.TrimRight(base, "/"),
		authorization: "Bearer " + options.Token,
		http:          client,
	}, nil
}

func (p *identityProvider) Name() components.EnforcementProvider { return p.name }

func (p *identityProvider) Run(ctx context.Context, action components.EnforcementAction, userID string) ([]components.EnforcementAction, error) {
	if userID == "" {
		return nil, errors.New("noresponse: user id must be non-empty")
	}
	steps, ok := p.spec.Actions[action]
	if !ok {
		return nil, fmt.Errorf("noresponse: unknown action %q", action)
	}
	call := &providerCall{provider: p, user: userID}
	return call.runSteps(ctx, steps)
}

type customProvider map[components.EnforcementAction]func(ctx context.Context, userID string) ([]components.EnforcementAction, error)

// CustomProvider is your own user store: one function per action you
// support. An action without one fails.
func CustomProvider(handlers map[components.EnforcementAction]func(ctx context.Context, userID string) ([]components.EnforcementAction, error)) ActionProvider {
	return customProvider(handlers)
}

func (c customProvider) Name() components.EnforcementProvider {
	return components.EnforcementProviderCustom
}

func (c customProvider) Run(ctx context.Context, action components.EnforcementAction, userID string) ([]components.EnforcementAction, error) {
	handler, ok := c[action]
	if !ok || handler == nil {
		return nil, fmt.Errorf("noresponse: CustomProvider has no %s handler", action)
	}
	return handler(ctx, userID)
}

// providerCall is one action's calls, sharing its rate-limit budget.
type providerCall struct {
	provider *identityProvider
	user     string
	waited   time.Duration
}

func (c *providerCall) runSteps(ctx context.Context, steps []tableStep) ([]components.EnforcementAction, error) {
	var alsoRan []components.EnforcementAction
	for _, step := range steps {
		if step.Each != nil {
			items, err := c.collect(ctx, step)
			if err != nil {
				return nil, err
			}
			for _, item := range items {
				if _, err := c.send(ctx, step.Call, item, nil); err != nil {
					return nil, err
				}
			}
			continue
		}
		if _, err := c.send(ctx, step.Call, "", nil); err != nil {
			var refused *ProviderActionError
			fallback := step.Fallback
			if fallback == nil || !errors.As(err, &refused) || refused.Status != fallback.Status || refused.Code != fallback.Code {
				return nil, err
			}
			ran, err := c.runSteps(ctx, fallback.Steps)
			if err != nil {
				return nil, err
			}
			alsoRan = append(alsoRan, ran...)
			if fallback.Reports != "" {
				alsoRan = append(alsoRan, fallback.Reports)
			}
		}
	}
	return alsoRan, nil
}

// collect returns every matching item id across the list's pages, collected
// before any is acted on.
func (c *providerCall) collect(ctx context.Context, step tableStep) ([]string, error) {
	each := step.Each
	var ids []string
	cursor := ""
	for index := 0; index < actionTable.Limits.MaxPages; index++ {
		extra := map[string]string{}
		switch each.Page.Kind {
		case "offset":
			extra[each.Page.Param] = strconv.Itoa(index * each.Page.Size)
		case "index":
			extra[each.Page.Param] = strconv.Itoa(index)
		default:
			if cursor != "" {
				extra[each.Page.Param] = cursor
			}
		}
		body, err := c.send(ctx, each.List, "", extra)
		if err != nil {
			return nil, err
		}
		items, _ := body.([]any)
		if object, ok := body.(map[string]any); ok {
			items, _ = object["data"].([]any)
		}
		for _, entry := range items {
			item, _ := entry.(map[string]any)
			id, _ := item["id"].(string)
			if id == "" {
				continue
			}
			matches := true
			for key, want := range each.Where {
				if item[key] != want {
					matches = false
				}
			}
			if matches {
				ids = append(ids, id)
			}
		}
		if each.Page.Kind == "cursor" {
			var next any = body
			for _, key := range each.Page.Next {
				object, _ := next.(map[string]any)
				next = object[key]
			}
			value, _ := next.(string)
			if value == "" {
				break
			}
			cursor = value
		} else if len(items) < each.Page.Size {
			break
		}
	}
	return ids, nil
}

func fill(value any, user, item string) any {
	switch v := value.(type) {
	case string:
		return strings.ReplaceAll(strings.ReplaceAll(v, "{user}", user), "{item}", item)
	case []any:
		out := make([]any, len(v))
		for i, entry := range v {
			out[i] = fill(entry, user, item)
		}
		return out
	case map[string]any:
		out := make(map[string]any, len(v))
		for key, entry := range v {
			out[key] = fill(entry, user, item)
		}
		return out
	default:
		return v
	}
}

// rateLimitWait is how long a 429 asks to wait.
func rateLimitWait(header http.Header, retry int) time.Duration {
	number := func(name string) (float64, bool) {
		value, err := strconv.ParseFloat(strings.TrimSpace(header.Get(name)), 64)
		return value, err == nil && !math.IsInf(value, 0) && !math.IsNaN(value)
	}
	if seconds, ok := number("Retry-After"); ok && seconds >= 0 {
		return time.Duration(math.Min(seconds, 3600) * float64(time.Second))
	}
	if at, ok := number("X-RateLimit-Reset"); ok {
		wait := time.Until(time.Unix(0, int64(math.Min(at, 1e10)*float64(time.Second))))
		return max(wait, 0)
	}
	return time.Duration(actionTable.Limits.BackoffMS) * time.Millisecond << retry
}

// errorCode is the provider's error code: Auth0's errorCode, WorkOS's code or
// Clerk's errors[0].code.
func errorCode(body []byte) string {
	var parsed struct {
		ErrorCode any `json:"errorCode"`
		Code      any `json:"code"`
		Errors    []struct {
			Code any `json:"code"`
		} `json:"errors"`
	}
	if json.Unmarshal(body, &parsed) != nil {
		return ""
	}
	for _, code := range []any{parsed.ErrorCode, parsed.Code} {
		if text, ok := code.(string); ok && text != "" {
			return text
		}
	}
	if len(parsed.Errors) > 0 {
		if text, ok := parsed.Errors[0].Code.(string); ok {
			return text
		}
	}
	return ""
}

// send makes one admin API call. A 404 is done (nil); a 429 is waited out
// inside the action's budget; any other failure is a *ProviderActionError.
func (c *providerCall) send(ctx context.Context, request tableRequest, item string, extra map[string]string) (any, error) {
	p := c.provider
	path := strings.ReplaceAll(strings.ReplaceAll(request.Path, "{user}", url.PathEscape(c.user)), "{item}", url.PathEscape(item))
	query := url.Values{}
	for key, value := range request.Query {
		query.Set(key, fill(value, c.user, item).(string))
	}
	for key, value := range extra {
		query.Set(key, value)
	}
	target := p.base + path
	if len(query) > 0 {
		target += "?" + query.Encode()
	}
	var payload []byte
	if request.HasBody {
		encoded, err := json.Marshal(fill(request.Body, c.user, item))
		if err != nil {
			return nil, err
		}
		payload = encoded
	}
	label := fmt.Sprintf("%s %s %s", p.name, request.Method, request.Path)
	budget := time.Duration(actionTable.Limits.BudgetMS) * time.Millisecond
	for retry := 0; ; retry++ {
		req, err := http.NewRequestWithContext(ctx, request.Method, target, bytes.NewReader(payload))
		if err != nil {
			return nil, err
		}
		req.Header.Set("Authorization", p.authorization)
		req.Header.Set("Accept", "application/json")
		if request.HasBody {
			req.Header.Set("Content-Type", "application/json")
		}
		response, err := p.http.Do(req)
		if err != nil {
			return nil, &ProviderActionError{Provider: string(p.name), Status: 0, Message: label + " failed: " + err.Error()}
		}
		body, err := io.ReadAll(io.LimitReader(response.Body, 1<<20))
		response.Body.Close()
		if err != nil {
			return nil, &ProviderActionError{Provider: string(p.name), Status: 0, Message: label + " failed: " + err.Error()}
		}
		if response.StatusCode == http.StatusTooManyRequests && retry < actionTable.Limits.Retries {
			wait := rateLimitWait(response.Header, retry)
			if c.waited+wait <= budget {
				c.waited += wait
				select {
				case <-ctx.Done():
					return nil, ctx.Err()
				case <-time.After(wait):
				}
				continue
			}
		}
		if response.StatusCode == http.StatusNotFound {
			return nil, nil
		}
		if response.StatusCode < 200 || response.StatusCode > 299 {
			return nil, &ProviderActionError{
				Provider: string(p.name),
				Status:   response.StatusCode,
				Message:  fmt.Sprintf("%s answered %d", label, response.StatusCode),
				Code:     errorCode(body),
			}
		}
		if len(body) == 0 {
			return nil, nil
		}
		var parsed any
		if json.Unmarshal(body, &parsed) != nil {
			return nil, nil
		}
		return parsed, nil
	}
}
